use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::io::Write;
use std::fs::OpenOptions;

/// Audit log entry with normalized username for consistent lookups
#[derive(Debug, Clone)]
pub struct AuditEntry {
    pub timestamp: u64,
    pub username: String,
    pub action: String,
    pub resource: String,
    pub allowed: bool,
}

/// Policy engine that checks access based on username
pub struct PolicyEngine {
    blocked_users: Vec<String>,
}

impl PolicyEngine {
    pub fn new() -> Self {
        PolicyEngine {
            blocked_users: vec![
                "admin".to_string(),
                "root".to_string(),
                "system".to_string(),
            ],
        }
    }

    /// Check if a user is allowed to perform an action
    pub fn check_access(&self, username: &str, _action: &str, _resource: &str) -> bool {
        let normalized = self.normalize_for_policy(username);
        !self.blocked_users.iter().any(|b| b == &normalized)
    }

    /// NFKC normalization for policy comparison - handles all Unicode equivalences
    fn normalize_for_policy(&self, input: &str) -> String {
        let mut result = String::new();
        for ch in input.chars() {
            match ch {
                // NFKC maps fullwidth Latin letters to ASCII equivalents
                '\u{FF41}'..='\u{FF5A}' => {
                    let ascii = (ch as u32 - 0xFF41 + 0x61) as u8 as char;
                    result.push(ascii);
                }
                '\u{FF21}'..='\u{FF3A}' => {
                    let ascii = (ch as u32 - 0xFF21 + 0x61) as u8 as char;
                    result.push(ascii);
                }
                _ => result.push(ch.to_ascii_lowercase()),
            }
        }
        result
    }
}

/// Audit logger that records all access attempts
pub struct AuditLogger {
    log_path: String,
    entries: Arc<Mutex<Vec<AuditEntry>>>,
    alert_callback: Option<Box<dyn Fn(&AuditEntry) + Send>>,
}

impl AuditLogger {
    pub fn new(log_path: &str) -> Self {
        AuditLogger {
            log_path: log_path.to_string(),
            entries: Arc::new(Mutex::new(Vec::new())),
            alert_callback: None,
        }
    }

    pub fn set_alert_callback(&mut self, cb: Box<dyn Fn(&AuditEntry) + Send>) {
        self.alert_callback = Some(cb);
    }

    /// Escape control characters (newlines, CR, etc.) to prevent log injection
    /// when writing free-form fields into the single-line log format.
    fn escape_for_log_line(input: &str) -> String {
        let mut out = String::with_capacity(input.len());
        for ch in input.chars() {
            match ch {
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                c if c.is_control() => {
                    out.push_str(&format!("\\u{{{:04X}}}", c as u32));
                }
                c => out.push(c),
            }
        }
        out
    }

    /// Log an audit entry - uses same NFKC normalization as policy engine
    pub fn log_entry(&self, entry: AuditEntry) {
        let display_entry = AuditEntry {
            timestamp: entry.timestamp,
            username: self.normalize_for_display(&entry.username),
            action: entry.action.clone(),
            resource: entry.resource.clone(),
            allowed: entry.allowed,
        };

        // Write to file (escape control characters to prevent log injection)
        if let Ok(mut file) = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.log_path)
        {
            let _ = writeln!(
                file,
                "[{}] user={} action={} resource={} allowed={}",
                display_entry.timestamp,
                Self::escape_for_log_line(&display_entry.username),
                Self::escape_for_log_line(&display_entry.action),
                Self::escape_for_log_line(&display_entry.resource),
                display_entry.allowed
            );
        }

        // Trigger alert on denied access
        if !display_entry.allowed {
            if let Some(ref cb) = self.alert_callback {
                cb(&display_entry);
            }
        }

        let mut entries = self.entries.lock().unwrap();
        entries.push(display_entry);
    }

    /// Normalize for display - uses NFKC same as policy to ensure consistency
    fn normalize_for_display(&self, input: &str) -> String {
        let mut result = String::new();
        for ch in input.chars() {
            match ch {
                '\u{FF41}'..='\u{FF5A}' => {
                    let ascii = (ch as u32 - 0xFF41 + 0x61) as u8 as char;
                    result.push(ascii);
                }
                '\u{FF21}'..='\u{FF3A}' => {
                    let ascii = (ch as u32 - 0xFF21 + 0x61) as u8 as char;
                    result.push(ascii);
                }
                '\u{0041}'..='\u{005A}' => result.push(ch.to_ascii_lowercase()),
                _ => result.push(ch),
            }
        }
        result
    }

    /// Search audit log for entries by username
    pub fn search_by_user(&self, username: &str) -> Vec<AuditEntry> {
        let normalized_search = self.normalize_for_display(username);
        let entries = self.entries.lock().unwrap();
        entries
            .iter()
            .filter(|e| e.username == normalized_search)
            .cloned()
            .collect()
    }
}

/// Main monitoring agent that ties policy and logging together
pub struct MonitoringAgent {
    policy: PolicyEngine,
    logger: AuditLogger,
}

impl MonitoringAgent {
    pub fn new(log_path: &str) -> Self {
        MonitoringAgent {
            policy: PolicyEngine::new(),
            logger: AuditLogger::new(log_path),
        }
    }

    /// Process an access request - check policy and log result
    pub fn process_request(
        &self,
        timestamp: u64,
        username: &str,
        action: &str,
        resource: &str,
    ) -> bool {
        let allowed = self.policy.check_access(username, action, resource);

        let entry = AuditEntry {
            timestamp,
            username: username.to_string(),
            action: action.to_string(),
            resource: resource.to_string(),
            allowed,
        };

        self.logger.log_entry(entry);
        allowed
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_user_allowed() {
        let agent = MonitoringAgent::new("/tmp/test_audit.log");
        assert!(agent.process_request(1000, "alice", "read", "/data/report.csv"));
    }

    #[test]
    fn test_admin_blocked() {
        let agent = MonitoringAgent::new("/tmp/test_audit.log");
        assert!(!agent.process_request(1001, "admin", "write", "/etc/passwd"));
    }

    #[test]
    fn test_fullwidth_admin_blocked() {
        let agent = MonitoringAgent::new("/tmp/test_audit.log");
        // Fullwidth 'admin' = \u{FF41}\u{FF44}\u{FF4D}\u{FF49}\u{FF4E}
        let fullwidth_admin = "\u{FF41}\u{FF44}\u{FF4D}\u{FF49}\u{FF4E}";
        assert!(!agent.process_request(1002, fullwidth_admin, "write", "/etc/shadow"));
    }

    #[test]
    fn test_audit_search() {
        let agent = MonitoringAgent::new("/tmp/test_audit.log");
        agent.process_request(2000, "bob", "read", "/data/file.txt");
        let results = agent.logger.search_by_user("bob");
        assert_eq!(results.len(), 1);
    }
}
